  if(isStandalone()){state.copyRules=[rule,...(state.copyRules||[]).filter(x=>x.id!==id)];if(kind==='profile'&&!(state.trackedProfiles||[]).some(x=>x.toLowerCase()===subject.toLowerCase()))state.trackedProfiles=[...(state.trackedProfiles||[]),subject];if(kind==='wallet'&&!(state.trackedWallets||[]).some(x=>x.toLowerCase()===subject.toLowerCase()))state.trackedWallets=[...(state.trackedWallets||[]),subject];localCopyEval(rule);render();toast(`Copy strategy active for ${rule.name||subject}`);return rule}
