function copyFormMarkup(rule,name,subtitle){const checked=v=>v!==false?'checked':'';return `<span class="kicker">COPY STRATEGY</span><div class="copy-drawer-title"><div><h3>${esc(name)}</h3><p>${esc(subtitle)}</p></div><span class="copy-live-badge">AUTOPILOT</span></div><div class="copy-toggle-grid"><label><input id="copyBuys" type="checkbox" ${checked(rule.copyBuys)}><span>COPY BUYS</span></label><label><input id="copySells" type="checkbox" ${checked(rule.copySells)}><span>COPY SELLS</span></label><label><input id="copyFast" type="checkbox" ${checked(rule.fastFollow)}><span>FAST FOLLOW</span></label></div><div class="copy-form-grid"><label>SIZE / TRADE<input id="copySize" type="number" min="0.001" step="0.001" value="${Number(rule.sizeEth??.05)}"><small>ETH</small></label><label>MAX MARKET CAP<input id="copyMaxMc" type="number" min="0" step="10000" value="${Number(rule.maxMarketCap??3000000)}"><small>USD</small></label><label>MIN LIQUIDITY<input id="copyMinLiq" type="number" min="0" step="1000" value="${Number(rule.minLiquidity??20000)}"><small>USD</small></label><label>MAX TAX<input id="copyMaxTax" type="number" min="0" step="0.1" value="${Number(rule.maxTaxPct??3)}"><small>%</small></label><label>SLIPPAGE<input id="copySlip" type="number" min="0.1" step="0.1" value="${Number(rule.slippagePct??10)}"><small>%</small></label><label>MIN CONVICTION<input id="copyMinConv" type="number" min="1" step="1" value="${Number(rule.minConviction??1)}"><small>wallets</small></label><label>TAKE PROFIT<input id="copyTp" type="number" min="0" step="10" value="${Number(rule.takeProfitPct??200)}"><small>%</small></label><label>STOP LOSS<input id="copySl" type="number" max="0" step="5" value="${Number(rule.stopLossPct??-35)}"><small>%</small></label><label>MAX OPEN<input id="copyMaxOpen" type="number" min="1" max="50" step="1" value="${Number(rule.maxConcurrent??5)}"><small>positions</small></label></div><div class="copy-rule-explainer"><b>ORDER LOGIC</b><span>BUY signal → risk filters → conviction gate → COPY native queue → executor/relayer. SELL signal → native exit request if Copy Sells is enabled.</span></div><div class="copy-drawer-actions"><button id="copySave" class="primary">SAVE & ARM COPY</button>${rule.id?'<button id="copyDisable" class="danger-ghost">DISABLE</button>':''}</div>`}
function openCopyRuleDrawer(rule){if(!rule)return;$('#drawerContent').innerHTML=copyFormMarkup(rule,rule.name||rule.subject,rule.kind==='profile'?`@${rule.subject} · Fomo profit hunter`:`${addr(rule.subject)} · Robinhood wallet`);$('#profileDrawer').classList.add('open');$('#profileDrawer').setAttribute('aria-hidden','false');$('#drawerBackdrop').classList.add('open');wireCopyForm(rule)}
function openCopyConfig(key){const w=(state.hunters||[]).find(x=>hunterKey(x)===String(key||'').toLowerCase());if(!w?.handle)return toast('Copy requires a public trader handle');const existing=copyRuleForHunter(w)||{kind:'profile',subject:w.handle,name:traderName(w),enabled:true,copyBuys:true,copySells:true,fastFollow:true,sizeEth:.05,maxMarketCap:3000000,minLiquidity:20000,maxTaxPct:3,slippagePct:10,minConviction:1,takeProfitPct:200,stopLossPct:-35,maxConcurrent:5};$('#drawerContent').innerHTML=copyFormMarkup(existing,traderName(w),`@${w.handle} · DNA ${w.score} · ${money(fomoWindowValue(w))} ${activeWindow.toUpperCase()}`);$('#profileDrawer').classList.add('open');$('#profileDrawer').setAttribute('aria-hidden','false');$('#drawerBackdrop').classList.add('open');wireCopyForm(existing)}
function wireCopyForm(base){const val=id=>Number($(id)?.value||0),rule={...base};$('#copySave').onclick=async()=>{const payload={...rule,enabled:true,copyBuys:$('#copyBuys').checked,copySells:$('#copySells').checked,fastFollow:$('#copyFast').checked,sizeEth:val('#copySize'),maxMarketCap:val('#copyMaxMc'),minLiquidity:val('#copyMinLiq'),maxTaxPct:val('#copyMaxTax'),slippagePct:val('#copySlip'),minConviction:val('#copyMinConv'),takeProfitPct:val('#copyTp'),stopLossPct:val('#copySl'),maxConcurrent:val('#copyMaxOpen')};const saved=await saveCopyRule(payload);if(saved)closeProfile()};const d=$('#copyDisable');if(d)d.onclick=async()=>{await removeCopyRule(base.id);closeProfile()}}
function openProfile(key){const w=(state.hunters||[]).find(x=>hunterKey(x)===String(key||'').toLowerCase());if(!w)return;const trades=w.handle?allFlow().filter(x=>String(x.handle||'').toLowerCase()===String(w.handle).toLowerCase()).slice(0,10):[],watched=w.handle&&(state.trackedProfiles||[]).some(x=>x.toLowerCase()===String(w.handle).toLowerCase()),focus=hunterToken(w),handle=w.handle?`@${esc(w.handle)}`:'Fomo leaderboard profile';$('#drawerContent').innerHTML=`<span class="kicker">FOMO PROFIT PROFILE</span><div class="drawer-user"><span class="avatar big">${initials(traderName(w))}</span><div><h3>${esc(traderName(w))}</h3><p>${handle} · ${archetype(w)} ${w.followers?`· ${short(w.followers)} followers`:''}</p></div><span class="drawer-dna">DNA <b>${w.score}</b></span></div><div class="drawer-pnl"><div><span>24H PNL</span><b class="${Number(w.pnl24h)<0?'negative':''}">${money(w.pnl24h)}</b></div><div><span>7D PNL</span><b class="${Number(w.pnl7d)<0?'negative':''}">${money(w.pnl7d)}</b></div><div><span>30D PNL</span><b class="${Number(w.pnl30d)<0?'negative':''}">${money(w.pnl30d)}</b></div></div>${focus?`<div class="focus-position"><span>${esc(focus.relation||'RH TOKEN')}</span>${tokenPill(focus)}${w.focusPosition?.note?`<p>${esc(w.focusPosition.note)}</p>`:''}</div>`:''}<div class="drawer-meta"><div><span>COINS</span><b>${w.coins??'—'}</b></div><div><span>TRADES</span><b>${w.trades?short(w.trades):w.recentTrades||'—'}</b></div><div><span>${activeWindow.toUpperCase()} RANK</span><b>#${fomoWindowRank(w)||'—'}</b></div></div><div class="drawer-section"><div class="drawer-section-head"><b>CONFIRMED ROBINHOOD ACTIVITY</b><span>${trades.length} recent</span></div>${trades.length?trades.map(t=>`<div class="drawer-trade"><span class="${t.side==='SELL'?'sell-txt':'buy-txt'}">${t.side}</span><div>${tokenPill({...t,address:t.tokenAddress||t.token},{compact:true})}<small>${t.marketCap?`MC ${usd(t.marketCap)} · `:''}${ago(t.createdAt)}</small></div><strong>${t.usdAmount?usd(t.usdAmount):esc(t.amount||'—')}</strong></div>`).join(''):'<div class="drawer-empty">No confirmed Robinhood trade attached to this profile yet.</div>'}</div>${w.handle?`<div class="drawer-actions-stack"><button class="primary drawer-copy" data-drawer-copy="${escAttr(key)}">${copyRuleForHunter(w)?.enabled?'EDIT COPY STRATEGY':'COPY THIS TRADER ↗'}</button><button class="drawer-watch secondary-drawer-btn" data-drawer-watch="${escAttr(w.handle)}">${watched?'WATCHING':'ADD TO COPY LIST'}</button></div>`:''}`;$('#profileDrawer').classList.add('open');$('#profileDrawer').setAttribute('aria-hidden','false');$('#drawerBackdrop').classList.add('open');const b=$('[data-drawer-watch]');if(b)b.onclick=async e=>{await toggleProfile(e.currentTarget.dataset.drawerWatch);closeProfile()};const c=$('[data-drawer-copy]');if(c)c.onclick=e=>openCopyConfig(e.currentTarget.dataset.drawerCopy)}
function closeProfile(){$('#profileDrawer').classList.remove('open');$('#profileDrawer').setAttribute('aria-hidden','true');$('#drawerBackdrop').classList.remove('open')}
function refreshRelativeTimes(){$$('.relative-time[data-time]').forEach(e=>e.textContent=ago(e.dataset.time))}
function initUi(){$$('[data-scroll]').forEach(b=>b.onclick=()=>$(b.dataset.scroll)?.scrollIntoView({behavior:'smooth',block:'start'}));$$('.topbar nav a[href^="#"]').forEach(a=>a.onclick=e=>{e.preventDefault();const t=$(a.getAttribute('href'));if(t)t.scrollIntoView({behavior:'smooth',block:'start'})});if('IntersectionObserver'in window){const links=new Map($$('.topbar nav a[href^="#"]').map(a=>[a.getAttribute('href').slice(1),a])),io=new IntersectionObserver(entries=>{const hit=entries.filter(x=>x.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(!hit)return;links.forEach((a,id)=>a.classList.toggle('active',id===hit.target.id))},{rootMargin:'-70px 0px -60% 0px',threshold:[.05,.2,.5]});['hunters','flow','alpha','copytrade','fastfollow'].forEach(id=>{const el=document.getElementById(id);if(el)io.observe(el)})}$$('[data-window]').forEach(b=>b.onclick=()=>{activeWindow=b.dataset.window;$$('[data-window]').forEach(x=>x.classList.toggle('active',x===b));renderHunters()});$$('[data-minscore]').forEach(b=>b.onclick=()=>{minScore=Number(b.dataset.minscore);$$('[data-minscore]').forEach(x=>x.classList.toggle('active',x===b));renderAlpha()});$('#showMore').onclick=()=>{hunterLimit=Math.min(90,hunterLimit+15);renderHunters()};$('#watchForm').onsubmit=async e=>{e.preventDefault();const input=$('#watchInput'),address=input.value.trim();if(await addWallet(address))input.value=''};const arm=$('#ffArm');if(arm)arm.onclick=async()=>{if(!ffSelected)return toast('Pick a Smart Flow signal first');const sym=ffSelected.symbol||ffSelected.tokenSymbol||'TOKEN',tokenAddress=ffSelected.tokenAddress||ffSelected.token;if(!validAddr(tokenAddress))return toast('This signal has no executable token address');const size=Math.max(.001,Number.parseFloat($('#ffBuySize')?.value)||.05),payload={tradeId:flowKey(ffSelected),tokenAddress,symbol:sym,subjectName:ffSelected.displayName||ffSelected.handle||addr(ffSelected.wallet)||'Smart Flow',sourceTradeAt:ffSelected.createdAt,sizeEth:size,conviction:Number(ffSelected.uniqueBuyers||1),marketCap:Number(ffSelected.marketCap||0),liquidity:Number(ffSelected.liquidity||0)};if(isStandalone()){state.copyActivity=state.copyActivity||[];state.copyActivity.unshift({...payload,ruleId:'manual:fast-follow',kind:'manual',subject:'Fast Follow',createdAt:new Date().toISOString(),action:'BUY',status:'ARMED',reason:'manual Fast Follow · native execution queued'});renderCopyCenter();toast(`Fast Follow queued for $${sym}`);return}const r=await fetch('/api/manual-arm',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});if(r.ok){await load();toast(`Fast Follow queued for $${sym}`)}else toast('Could not arm this signal')};const sig=$('#ffSignal');if(sig)sig.onclick=()=>$('#flow')?.scrollIntoView({behavior:'smooth',block:'center'});$('#drawerClose').onclick=closeProfile;$('#drawerBackdrop').onclick=closeProfile;document.addEventListener('keydown',e=>{if(e.key==='Escape')closeProfile()})}
if(window.__COPY_BOOTSTRAP__){state=clone(window.__COPY_BOOTSTRAP__);seedMarketPulse();render()}
initUi();setInterval(()=>{const s=Math.floor((Date.now()-started)/1000),h=String(Math.floor(s/3600)).padStart(2,'0'),m=String(Math.floor(s%3600/60)).padStart(2,'0'),q=String(s%60).padStart(2,'0');$('#uptime').textContent=`${h}:${m}:${q}`;refreshRelativeTimes()},1000);load().then(connectStream).catch(()=>{setTimeout(()=>load().catch(()=>{}),1800);connectStream()});
